tlas.json:1230:      \"model_name\": \"AlphaGenome\",\ndocs/input-representation-atlas/data/atlas.json:1231:      \"record_id\": \"june_update_2026-06-10__rec_000194\",\ndocs/input-representation-atlas/data/atlas.json:1232:      \"study_id\": \"study_44ce36825624\",\ndocs/input-representation-atlas/data/atlas.json:1233:      \"paper_title\": \"Bio-BLIP: A Multimodal Architecture for Transferable Reasoning in Genomic Variant Interpretation\",\ndocs/input-representation-atlas/data/atlas.json:1234:      \"doi\": \"10.64898/2026.05.12.724740\",\ndocs/input-representation-atlas/data/atlas.json:1235:      \"paper_url\": \"https://doi.org/10.64898/2026.05.12.724740\",\ndocs/input-representation-atlas/data/atlas.json:1236:      \"route_count\": 1,\ndocs/input-representation-atlas/data/atlas.json:1237:      \"configuration_count\": 1,\ndocs/input-representation-atlas/data/atlas.json:1238:      \"family_counts\": {\ndocs/input-representation-atlas/data/atlas.json:1239:        \"discrete_biological_symbol_stream\": 1\ndocs/input-representation-atlas/data/atlas.json:1240:      },\ndocs/input-representation-atlas/data/atlas.json:1241:      \"subtype_counts\": {\ndocs/input-representation-atlas/data/atlas.json:1242:        \"native_biological_token_stream\": 1\ndocs/input-representation-atlas/data/atlas.json:1243:      },\ndocs/input-representation-atlas/data/atlas.json:1244:      \"families\": [\ndocs/input-representation-atlas/data/atlas.json:1245:        \"discrete_biological_symbol_stream\"\ndocs/input-representation-atlas/data/atlas.json:1246:      ],\ndocs/input-representation-atlas/data/atlas.json:1247:      \"subtypes\": [\ndocs/input-representation-atlas/data/atlas.json:1248:        \"native_biological_token_stream\"\ndocs/input-representation-atlas/data/atlas.json:1249:      ],\ndocs/input-representation-atlas/data/atlas.json:1250:      \"modalities\": [\ndocs/input-representation-atlas/data/atlas.json:1251:        \"DNA sequence\"\ndocs/input-representation-atlas/data/atlas.json:1252:      ],\ndocs/input-representation-atlas/data/atlas.json:1253:      \"lifecycle_phases\": [\ndocs/input-representation-atlas/data/atlas.json:1254:        \"inference\"\ndocs/input-representation-atlas/data/atlas.json:1255:      ],\ndocs/input-representation-atlas/data/atlas.json:1256:      \"fusion_topologies\": [\ndocs/input-representation-atlas/data/atlas.json:1257:        \"tokenizer_sequence\"\ndocs/input-representation-atlas/data/atlas.json:1258:      ],\ndocs/input-representation-atlas/data/atlas.json:1259:      \"text_roles\": [\ndocs/input-representation-atlas/data/atlas.json:1260:        \"no_text_on_this_route\"\ndocs/input-representation-atlas/data/atlas.json:1261:      ],\ndocs/input-representation-atlas/data/atlas.json:1262:      \"figure\": {\ndocs/input-representation-atlas/data/atlas.json:1263:        \"asset\": \"assets/figures/june_update_2026_06_10_rec_000194_figure_001.png\",\ndocs/input-representation-atlas/data/atlas.json:1264:        \"source_path\": \"data/docling_include_vlm_52_2026-07-10_nolimits/figures/june_update_2026_06_10_rec_000194/figure_001.png\",\ndocs/input-representation-atlas/data/atlas.json:1265:        \"figure_index\": 1,\ndocs/input-representation-atlas/data/atlas.json:1266:        \"caption\": \"Figure 1: (a) Embeddings (E) from Biological Foundation Models (BioFMs) are input to Bio-BLIP to provide multiple modalities of information, here from AlphaGenome , GenePT , and ESM-2 . (b) Modality-specific Q-formers align diverse biological embeddings with captions of genomic variants, which contain functional and locational information. The Q-formers output query tokens encoding relevant information from each modality. (c) The Master Qformer integrates modality-specific tokens through cross-attention, producing a fixed-length visual prefix (d) The LLM, its weights frozen , takes as input the multimodal prefix and a prompt. During pretraining, the LLM loss backpropagates only to train the Q-formers. Pretraining and evaluation is conducted on variant annotation; all weights are frozen and the model is then applied to downstream evaluation tasks.\",\ndocs/input-representation-atlas/data/atlas.json:1267:        \"description\": \"SCIENTIFIC_FIGURE\\n\\nModel architecture/workflow diagram labeled “BioBLIP Architecture.” It shows panel-like labels A-D: A indicates multiple input embedding sources (AlphaGenome Ref/Alt embeddings, GenoPT embeddings, ESM Protein embeddings) as blue triangular inputs E1, E2, … En; B shows modality-specific query modules (“DNA Qformer,” “Gene Qformer,” “Protein Qformer”) producing DNA/gene/protein-specific query tokens; C shows a “Master Qformer” receiving query tokens plus an instruction describing genomic variant context and outputting a fixed-length variant prefix; D shows this prefix fed with a text prompt into a “Frozen LLM,” producing a generated variant annotation JSON.\\n\\nNo quantitative axes or plots are present. The biological/model content shown is a multimodal genomic variant annotation architecture integrating DNA, gene, and protein embeddings for tasks including variant annotation, target gene identification, and regulatory variant prioritization. Main visible finding/claim: BioBLIP uses chained Q-former modules to convert heterogeneous biological embeddings into an LLM-compatible prefix for structured variant annotation.\",\ndocs/input-representation-atlas/data/atlas.json:1268:        \"page_no\": 2,\ndocs/input-representation-atlas/data/atlas.json:1269:        \"selection_score\": 105,\ndocs/input-representation-atlas/data/atlas.json:1270:        \"selection_reasons\": [\ndocs/input-representation-atlas/data/atlas.json:1271:          \"1 model-name tokens match\",\ndocs/input-representation-atlas/data/atlas.json:1272:          \"architecture/workflow figure\",\ndocs/input-representation-atlas/data/atlas.json:1273:          \"model name appears in figure text\"\ndocs/input-representation-atlas/data/atlas.json:1274:        ],\ndocs/inp